// recipe: pointer-hit
// args: none
// returns: ok, pointerX, pointerY, worldX, worldY, hits, name, tag, layer, distance, error, detail
// What the pointer is actually over: the top `Physics2D.RaycastAll` hit under `Input.mousePosition`, named. The game's
// use key starts dragging only when its own raycast finds a `UsableObject` under the pointer
// (`PlayerCamera.cs:1509-1513`), so "the key did nothing" and "the pointer was not on the door" read the same without this.
((System.Func<string>)(() => { var camera = UnityEngine.Camera.main; if (camera == null) { return "{\"ok\":false,\"error\":\"no-camera\"}"; } var mouse = UnityEngine.Input.mousePosition; var world = camera.ScreenToWorldPoint(new UnityEngine.Vector3(mouse.x, mouse.y, -camera.transform.position.z)); var hits = UnityEngine.Physics2D.RaycastAll(new UnityEngine.Vector2(world.x, world.y), UnityEngine.Vector2.zero, 0.01f); var engine = System.Globalization.CultureInfo.InvariantCulture; var name = ""; var tag = ""; var layer = ""; var distance = -1f; foreach (var hit in hits) { if (hit.transform == null) { continue; } name = hit.transform.name; tag = hit.transform.tag; layer = UnityEngine.LayerMask.LayerToName(hit.transform.gameObject.layer); distance = 0f; break; } return "{\"ok\":true,\"pointerX\":" + mouse.x.ToString("0.##", engine) + ",\"pointerY\":" + mouse.y.ToString("0.##", engine) + ",\"worldX\":" + world.x.ToString("0.###", engine) + ",\"worldY\":" + world.y.ToString("0.###", engine) + ",\"hits\":" + hits.Length.ToString(engine) + ",\"name\":\"" + name.Replace("\\", "/").Replace("\"", "''") + "\",\"tag\":\"" + tag + "\",\"layer\":\"" + layer + "\",\"distance\":" + distance.ToString("0.###", engine) + "}"; }))()
